cd /app && cat > solve.py <<'EOF'
import inspect, numpy as np, mteb

REV = "7999e1d3359715c523056ef9478215996d62a620"
NAME = "BAAI/bge-small-zh-v1.5"
QUERY = "terminal-bench"

model = mteb.get_model(NAME, revision=REV)

def enc(texts, kind):
    fn = model.encode
    params = inspect.signature(fn).parameters
    kw = {}
    if "task_name" in params: kw["task_name"] = "Retrieval"
    if "prompt_type" in params:
        try:
            from mteb.encoder_interface import PromptType
            kw["prompt_type"] = PromptType[kind]
        except Exception: pass
    elif "prompt_name" in params:
        kw["prompt_name"] = kind
    try:
        return np.asarray(fn(texts, **kw))
    except TypeError:
        return np.asarray(fn(texts))

docs = [l.rstrip("\n") for l in open("data.txt", encoding="utf-8") if l.strip()]
q = enc([QUERY], "query")
d = enc(docs, "passage")
def norm(x): return x / np.linalg.norm(x, axis=1, keepdims=True)
sims = (norm(q) @ norm(d).T)[0]
order = np.argsort(-sims)
for r, i in enumerate(order[:8], 1): print(r, round(float(sims[i]),4), docs[i][:70])
res = docs[order[4]]
open("result.txt", "w", encoding="utf-8").write(res + "\n")
print("RESULT:", res)
EOF
python3 solve.py

